export function translateLanguageName(lang: string): string {
  if (!lang) return '';
  const trimmed = lang.trim();
  const s = trimmed.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
  if (s === 'comun' || s.startsWith('comun')) return 'Common';
  if (s === 'enano' || s.startsWith('enano')) return 'Dwarvish';
  if (s === 'elfico' || s.startsWith('elf')) return 'Elvish';
  if (s === 'gigante' || s.startsWith('gigante')) return 'Giant';
  if (s === 'gnomo' || s.startsWith('gnom')) return 'Gnomish';
  if (s === 'trasgo' || s.startsWith('trasgo') || s.includes('goblin')) return 'Goblin';
  if (s === 'mediano' || s.startsWith('mediano') || s.includes('halfling')) return 'Halfling';
  if (s === 'orco' || s.startsWith('orco') || s.includes('orc')) return 'Orc';
  if (s === 'abisal' || s.startsWith('abisal') || s.includes('abyssal')) return 'Abyssal';
  if (s === 'celestial' || s.startsWith('celestial')) return 'Celestial';
  if (s === 'draconico' || s.startsWith('dracon') || s.includes('draconic')) return 'Draconic';
  if (s === 'habla profunda' || s.includes('profunda') || s.includes('deep speech')) return 'Deep Speech';
  if (s === 'infernal' || s.startsWith('infernal')) return 'Infernal';
  if (s === 'primordial' || s.startsWith('primordial')) return 'Primordial';
  if (s === 'silvano' || s.startsWith('silvano') || s.includes('sylvan')) return 'Sylvan';
  if (s === 'infracomun' || s.includes('infracomun') || s.includes('undercommon')) return 'Undercommon';
  if (s === 'kraul' || s.startsWith('kraul')) return 'Kraul';
  if (s === 'loxodonte' || s.startsWith('loxodon')) return 'Loxodon';
  if (s === 'minotauro' || s.startsWith('minotaur')) return 'Minotaur';
  if (s === 'vedalken' || s.startsWith('vedalken')) return 'Vedalken';
  if (s === 'druidico' || s.startsWith('druid')) return 'Druidic';
  if (s === 'jerga de ladrones' || s.includes('ladrones') || s.includes('thieves')) return "Thieves' Cant";
  if (LANGUAGE_NAME_MAP_EN[trimmed]) return LANGUAGE_NAME_MAP_EN[trimmed];
  return trimmed;
}

export function translateLanguageList(langs: string[]): string {
  if (!langs || langs.length === 0) return '';
  return langs.map(translateLanguageName).join(', ');
}

export function translateLanguageScript(script: string): string {
  if (!script) return 'None';
  const s = script.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
  if (s.includes('comun') || s.includes('common')) return 'Common';
  if (s.includes('enano') || s.includes('dwarv')) return 'Dwarvish';
  if (s.includes('elfico') || s.includes('elv')) return 'Elvish';
  if (s.includes('infernal')) return 'Infernal';
  if (s.includes('celestial')) return 'Celestial';
  if (s.includes('draconico') || s.includes('dragon') || s.includes('dracon')) return 'Draconic';
  if (s.includes('ningun') || s.includes('none')) return 'None';
  if (s.includes('kraul')) return 'Kraul';
  if (s.includes('vedalken')) return 'Vedalken';
  return script;
}

